import os
import time
import traceback

from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from taf.trafficgenerator.iperf import IperfFacade
from taf.ue.mtk.datatransfer.throughput_checker import IperfThroughputChecker
from taf.ue.mtk.datatransfer.temporary_log import DefaultTemporaryLog
from taf.ue.mtk.datatransfer.config import IperfDataTransferConfig
from taf.ue.mtk.utils import add_interface_trace
from taf.ue.mtk.exceptions import TrafficAppNotSupport, InvalidIperfLog


class IperfDataTransfer(LteDataTransfer):
    """IphoneIperfDataTransfer class"""

    def __init__(self, name, dt_definition, configuration, ue):
        """

        :param name: alias of data transfer
        :param dt_definition: object containing data transfer's details
        :param configuration: UE configuration from testline or yaml config file
        :param ue: UE object - MediaTek UE instance
        """
        super(IperfDataTransfer, self).__init__(name, dt_definition, configuration)
        self.dt_id = name
        self.ue_id = ue.id
        self.ue_pc = ue.ue_pc

        self._iperf = IperfFacade(self.logger)
        self._throughput_checker = IperfThroughputChecker(self.logger)
        self._throughput_checker.setup()
        self.dt_config = IperfDataTransferConfig(dt_definition,
                                                 configuration["data_transfer"]["iperf"],
                                                 ue,
                                                 self.logger)

        self._app_dt_config = None
        self._ue_dt_config = None
        self._temporary_log = None
        self._iperf_instance = None
        self._iperf_instances = None
        self._check_temporary_log_path = None

    def start(self):
        """
        Start data transfer with parameters defined in dt_definition passed during initialization.

        :return: None
        """
        raise NotImplementedError

    def stop(self):
        """
        Stop already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        raise NotImplementedError

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        raise NotImplementedError

    def await_finish(self, sleep_time=1):
        """
        Check if data transfer is finished

        :return: boolean
        """
        while True:
            if not self.is_running():
                break
            time.sleep(sleep_time)
        self.stop()

    def get_average_throughput(self, omit=0, end=0, tput_collection_src="iperf"):
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()'
        if data transfer is already finished
        or with currently available iperf intervals that were already transferred.
        :param omit: it is a delay in seconds to start counting the tput,
                     e.g. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput,
                    e.g. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :return: value of Average throughput in unit: KBits/sec
        """
        if tput_collection_src != "iperf":
            raise TrafficAppNotSupport('{} is not supported.'.format(tput_collection_src))
        # cause the NAA released iperf3 binary is 3.1.7 for CentOS platform, the output is not bitrate but bandwidth
        # so force to set the key column as bandwidth for uplink transport
        word = self._lookup_key_word_from_log(['Bandwidth', 'Bitrate'])
        if not word:
            raise InvalidIperfLog("Neither Bandwidth nor Bitrate in log")
        return self._get_iperf_average_throughput(word.lower(), omit=omit, end=end)

    def _lookup_key_word_from_log(self, words):
        with open(self._check_temporary_log_path, 'r') as f:
            content = f.read()
            for word in words:
                if word in content:
                    return word
            return None

    @staticmethod
    def _get_time_range(omit=0, end=0):
        omit = int(omit)
        end = int(end)
        if end and (omit >= end):
            raise ValueError("end must be greater than omit if end is not equal 0.")
        if omit == 0 and end == 0:
            return None
        elif end == 0:
            return [omit, ]
        else:
            return [omit, end]

    def _get_iperf_average_throughput(self, tput_column=None, omit=0, end=0):
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()'
        if data transfer is already finished
        or with currently available iperf intervals that were already transferred.
        :param tput_column: the key column indicating tput from output, None by default,
                     when iperf3, will be bitrate by default
        :param omit: it is a delay in seconds to start counting the tput,
                     e.g. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput,
                    e.g. '40' - it takes into account data till 40 second of transfer.
        :param tput_collection_src: source for collecting throughput data
        :return: value of Average throughput in unit: KBits/sec
        """
        time_range = self._get_time_range(omit, end)
        self.logger.info("current omit={} end={} and time_range={}.".format(omit, end, time_range))

        if self._app_dt_config["version"] == '3':
            self._throughput_checker.create_iperf3_throughput(
                file_path=self._check_temporary_log_path,
                protocol=self._dt_definition.protocol,
                time_range=time_range,
                column=tput_column)
        else:
            self._throughput_checker.create_iperf_throughput(
                file_path=self._check_temporary_log_path,
                protocol=self._dt_definition.protocol,
                time_range=time_range,
                column=tput_column)

        return self._throughput_checker.get_average_throughput()

    def check_data_transfer(self):
        """Check if data transfer is progressing"""
        return self.is_running()

    def reset_statistics(self):
        """
        Reset data transfer statistics on UE.

        :return: None
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownAlias`:
        if no such dt_name created before via start_data_transfer
        :raises: :py:class:`ute_common_abstract_core.exceptions.WrongAlias`:
        if dt_name doesn't point to DataTransfer object
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`:
        If reset data transfer statistics failed
        """
        self.logger.info("Skip reset_statistics method.")

    def get_data_transfer_statistics(self, omit=0, end=0):
        """Get all statistics of data transfer (intermediate results on timeline & final result).

        :param omit: it is a delay in seconds to start counting the tput,
                     e.g. '20' - 1st 20 seconds of datatransfer will be omitted.
        :param end: it is end time in seconds to stop counting the tput,
                    e.g. '40' - it takes into account data till 40 second of transfer.
        :return: dict of statistics contains "avg_tput", "min_tput", "max_tput", "raw_tput"
        """
        time_range = self._get_time_range(omit, end)

        word = self._lookup_key_word_from_log(['Bandwidth', 'Bitrate'])
        if not word:
            raise InvalidIperfLog("Neither Bandwidth nor Bitrate in log")

        if self._app_dt_config["version"] == '3':
            self._throughput_checker.create_iperf3_throughput(
                file_path=self._check_temporary_log_path,
                protocol=self._dt_definition.protocol,
                time_range=time_range,
                column=word.lower())
        else:
            self._throughput_checker.create_iperf_throughput(
                file_path=self._check_temporary_log_path,
                protocol=self._dt_definition.protocol,
                time_range=time_range,
                column=word.lower())
        return self._throughput_checker.get_throughput_statistics()

    def get_data_transfer_raw_data(self, output_file=None):
        """Get all raw statistics of data transfer final result"""
        with open(self._check_temporary_log_path, 'r') as content_file:
            raw_data = content_file.read()
        if output_file:
            self._save_file(raw_data, output_file)
        return raw_data

    def _save_file(self, data, file_path):
        if os.path.isfile(file_path):
            self.logger.debug('The old file {} is removed.'.format(file_path))
            os.remove(file_path)

        with open(file_path, 'w') as target_file:
            target_file.write(data)

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        self.logger.info("Skip get_datagram_loss method.")

    # private methods ##############################
    @add_interface_trace
    def _start_appserver_iperf(self):
        self._iperf.setup_iperfs(self._iperf_instances)
        self._iperf.start(self._iperf_instances, force_port_available=True)

    @add_interface_trace
    def _stop_appserver_iperf(self):
        self._iperf.stop(self._iperf_instances, force=True)
        self._iperf.teardown_iperfs()

    @add_interface_trace
    def _start_ue_iperf(self):
        self.ue_pc.start_data_transfer(ue_id=self.ue_id,
                                       data_transfer_id=self.dt_id,
                                       data_transfer_class="MtkIperf",
                                       data_transfer_config=self._ue_dt_config)

    @add_interface_trace
    def _stop_ue_iperf(self):
        self.ue_pc.stop_data_transfer(ue_id=self.ue_id, data_transfer_id=self.dt_id)

    def _save_ue_data_transfer_output(self):
        raw_data = self.ue_pc.get_data_transfer_output(ue_id=self.ue_id, data_transfer_id=self.dt_id, raw_output=True)
        file_path = self._temporary_log.ue_temporary_log_path

        self._save_file(raw_data['raw_output'], file_path)


class IperfUpLinkDataTransfer(IperfDataTransfer):
    """Object responsible for managing data transfer."""

    def __init__(self, name, dt_definition, configuration, ue):
        """

        :param name: alias of data transfer
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param ue: UE object - MediaTek UE instance
        """
        super(IperfUpLinkDataTransfer, self).__init__(name, dt_definition, configuration, ue)
        self._init_steps()

    def _init_steps(self):
        self._app_dt_config, self._ue_dt_config = self.dt_config.create_uplink_dt_config()
        self.logger.debug("Initialized data transfer config, appserver: {}, ue: {}".format(self._app_dt_config,
                                                                                           self._ue_dt_config))
        self._temporary_log = DefaultTemporaryLog(self._app_dt_config)
        self._temporary_log.generate_temporary_log_path()
        self._check_temporary_log_path = self._temporary_log.app_temporary_log_path

        self._create_iperf_instances()

    def _create_iperf_instances(self):
        if self._app_dt_config["version"] == '3':
            self._iperf_instance = self._iperf.create_iperf3_server(
                cmd_options=self._app_dt_config["cmd_options"],
                iperf_path=self._app_dt_config["binary_path"],
                log_path=self._temporary_log.app_temporary_log_path,
                host_configuration=self._app_dt_config["host_configuration"])
        else:
            self._iperf_instance = self._iperf.create_iperf_server(
                cmd_options=self._app_dt_config["cmd_options"],
                iperf_path=self._app_dt_config["binary_path"],
                log_path=self._temporary_log.app_temporary_log_path,
                host_configuration=self._app_dt_config["host_configuration"])
        self._iperf_instances = [self._iperf_instance, ]

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        self._start_appserver_iperf()
        self._start_ue_iperf()

    def stop(self):
        """
        Stops already running data transfer.
        :return: None
        """
        if self.is_running():
            self._stop_ue_iperf()
        self._save_ue_data_transfer_output()
        self._stop_appserver_iperf()

    def is_running(self):
        client_iperf_state = self.ue_pc.get_data_transfer_state(ue_id=self.ue_id, data_transfer_id=self.dt_id)
        return client_iperf_state == 'started'


class IperfDownLinkDataTransfer(IperfDataTransfer):
    """Object responsible for managing data transfer."""

    def __init__(self, name, dt_definition, configuration, ue):
        """

        :param name: alias of data transfer
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param ue: UE object - MediaTek UE instance
        """
        super(IperfDownLinkDataTransfer, self).__init__(name, dt_definition, configuration, ue)
        self._init_steps()

    def _init_steps(self):
        self._app_dt_config, self._ue_dt_config = self.dt_config.create_downlink_dt_config()
        self.logger.debug("Initialized data transfer config, appserver: {}, ue: {}".format(self._app_dt_config,
                                                                                           self._ue_dt_config))
        self._temporary_log = DefaultTemporaryLog(self._app_dt_config)
        self._temporary_log.generate_temporary_log_path()
        self._check_temporary_log_path = self._temporary_log.ue_temporary_log_path

        self._create_iperf_instances()

    def _create_iperf_instances(self):
        if self._app_dt_config["version"] == '3':
            self._iperf_instance = self._iperf.create_iperf3_client(
                cmd_options=self._app_dt_config["cmd_options"],
                iperf_path=self._app_dt_config["binary_path"],
                log_path=self._temporary_log.app_temporary_log_path,
                host_configuration=self._app_dt_config["host_configuration"])
        else:
            self._iperf_instance = self._iperf.create_iperf_client(
                cmd_options=self._app_dt_config["cmd_options"],
                iperf_path=self._app_dt_config["binary_path"],
                log_path=self._temporary_log.app_temporary_log_path,
                host_configuration=self._app_dt_config["host_configuration"])
        self._iperf_instances = [self._iperf_instance, ]

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        self._start_ue_iperf()
        self._start_appserver_iperf()

    def stop(self):
        """
        Stops already running data transfer.
        :return: None
        """
        self._stop_appserver_iperf()
        self._stop_ue_iperf()
        self._save_ue_data_transfer_output()

    def is_running(self):
        state = False
        try:
            state = self._iperf.is_running(self._iperf_instance)
        except Exception as err_info:
            msg = "data transfer is not running as exception: {}. \r\n traceback is {}"
            self.logger.warning(msg.format(err_info, traceback.format_exc()))
        finally:
            return state
